#include <bits/stdc++.h>
using namespace std;

bool check(int a, int b, int c, int x);

int main()
{
    int x, y;
    cin >> x >> y;

    int a = y, b = y, c = y;
    int sum = 0;

    while (check(a, b, c, x))
    {
        int k = min(a, min(b, c));

        if (k == b)
        {
            swap(a, b);
        }
        else if (k == c)
        {
            swap(a, c);
        }

        int s = b + c;
        if (s > x)
        {
            a = x;
        }
        else
        {
            a = s - 1;
        }
        sum++;
    }

    cout << sum;
    return 0;
}

bool check(int a, int b, int c, int x)
{
    return !(a == x && b == x && c == x);
}

